def wire(s):
 m=BRepBuilderAPI_MakePolygon();first=None
 for x,y in s['points']:
  p=gp_Pnt(float(x),float(y),float(s['z']));m.Add(p);first=p if first is None else first
 m.Add(first);m.Close();return m.Wire()
def build():
 loft=BRepOffsetAPI_ThruSections(True,RULED,1e-6);loft.CheckCompatibility(True)
 for s in SECTIONS:loft.AddWire(wire(s))
 loft.Build()
 if not loft.IsDone():raise RuntimeError('measured loft failed')
 shape=loft.Shape()
 if not BRepCheck_Analyzer(shape).IsValid():raise RuntimeError('invalid measured loft')
 wr=STEPControl_Writer();wr.Transfer(shape,STEPControl_AsIs);st=wr.Write(str(OUTPUT))
 if st!=IFSelect_RetDone:raise RuntimeError(f'STEP write {st}')
 return shape
